import React, { Component } from 'react'
import Table from 'react-bootstrap/Table'
import Button from 'react-bootstrap/Button'
import Form from 'react-bootstrap/Form'
import Spinner from 'react-bootstrap/Spinner'
import DataTable from 'react-data-table-component'

class CommentersTable extends Component {

    state = {
        selectedCommenters: [],
        enableCommentersSubmitButton: false
    }
  
  
    handleChange = event => {

        let index
        
        // check if the check box is checked or unchecked
        if (event.target.checked) {

          this.state.selectedCommenters.push(event.target.value);
          this.setState({selectedCommenters: this.state.selectedCommenters});
          console.log(this.state.selectedCommenters);
          
        } else {

          index = this.state.selectedCommenters.indexOf(event.target.value);
          this.state.selectedCommenters.splice(index, 1);
          this.setState({selectedCommenters: this.state.selectedCommenters});
          console.log(this.state.selectedCommenters);
          
        }
  
    }
    
    submitForm = () => {
        this.props.handleCommentersSubmit(this.state)
        //this.setState(this.initialState)
    }
    
    
    /*TableHeader = () => {
        return (
          <thead>
            <tr>
              <th>Commenter</th>
              <th>Messaged Before</th>
              <th>Send Message</th>
            </tr>
          </thead>
        )
      }*/
      
      
      tableHeaders = () => {
        return (
          [
            { name: 'Profile URL', selector: 'profileUrl', sortable: true },
            { name: 'Messaged Before', selector: 'messagedBefore', sortable: true },
            { name: 'Send Message', selector: 'sendMessage', sortable: true }
          ]
        )
      }
          
      /*
      TableBody = props => {
        const rows = props.commenters.map((row, index) => {
          return (
            <tr key={index}>
              <td><a target='_blank' rel="noopener noreferrer" href={row.profileUrl}>{row.profileUrl}</a></td>
              <td>{row.messagedBefore}</td>
              <td>
                <Form.Group>
                <Form.Check
                  type="checkbox"
                    id="" name="selectedCommenters" value={row.profileUrl} onChange={this.handleChange}/>
                </Form.Group>
              </td>
            </tr>
          )
        })
      
        return <tbody>{rows}</tbody>
      }*/
      
      
      tableBody = props => {
        
          let bodyArray = [];
          const rows = props.commenters.map((row, index) => {
            return (
              bodyArray.push({
                profileUrl : row.profileUrlToFind,
                messagedBefore : row.messagedBefore,
                sendMessage : <Form.Group><Form.Check type="checkbox" id="" name="selectedCommenters" value={row.profileUrl} onChange={this.handleChange}/></Form.Group>
                })
            )
        })
          
          return bodyArray;
      }

    
    render() {
        
        const { commenters } = this.props
  
        const showCommentersTable = this.props.showCommentersTable ? {display: 'block'} : {display: 'none'};
        
        const showCommentersSubmitButton = this.props.showCommentersSubmitButton ? {display: 'block'} : {display: 'none'};
        const showCommentersSubmitLoadingButton = this.props.showCommentersSubmitLoadingButton ? {display: 'block'} : {display: 'none'};
              
        const tableHeaders = this.tableHeaders;
        const tableBody = this.tableHeaders;
        
        
       const columns = [
          {
            name: 'Title',
            selector: 'title',
            sortable: true,
          },
          {
            name: 'Year',
            selector: 'year',
            sortable: true,
            right: true,
          },
        ];
        
        
         const data = [{ id: 1, title: 'Conan the Barbarian', year: '1982' }];
        
        return (
          
          tableBody

        )
    }

}

export default CommentersTable;
